  1	const { test } = require('node:test');
  2	const assert = require('node:assert/strict');
  3	const { topWords } = require('../src/textstats');
  4	
  5	// "keeper" x3, "lamp" x3, "night" x2, "tower" x2, "storm" x1. Stop words
  6	// (the, a, of, and, on, in, was) are present on purpose and must not appear.
  7	const PASSAGE = [
  8	  'The keeper lit the lamp. The lamp was old, and the keeper was older.',
  9	  'On a night of storm the tower shook; in the night the keeper climbed',
 10	  'the tower, lamp in hand.',
 11	].join(' ');
 12	
 13	const CASES = [
 14	  ["apple", 1, [{"word": "apple", "count": 1}]],
 15	  ["apple apple", 1, [{"word": "apple", "count": 2}]],
 16	  ["apple banana", 5, [{"word": "apple", "count": 1}, {"word": "banana", "count": 1}]],
 17	  ["banana apple", 5, [{"word": "apple", "count": 1}, {"word": "banana", "count": 1}]],
 18	  ["fig fig pear", 1, [{"word": "fig", "count": 2}]],
 19	  ["fig fig pear", 2, [{"word": "fig", "count": 2}, {"word": "pear", "count": 1}]],
 20	  ["kiwi kiwi lime lime", 2, [{"word": "kiwi", "count": 2}, {"word": "lime", "count": 2}]],
 21	  ["x y z", 2, [{"word": "x", "count": 1}, {"word": "y", "count": 1}]],
 22	];
 23	
 24	test('returns an empty array for the empty string', () => {
 25	  assert.deepEqual(topWords('', 5), []);
 26	});
 27	
 28	test('returns an empty array for punctuation and whitespace only', () => {
 29	  assert.deepEqual(topWords(' ... -- ?! \n', 5), []);
 30	});
 31	
 32	test('returns an empty array when every word is a stop word', () => {
 33	  assert.deepEqual(topWords('the and of the to a in it', 5), []);
 34	});
 35	
 36	test('returns an empty array when n is 0', () => {
 37	  assert.deepEqual(topWords('apple banana apple', 0), []);
 38	});
 39	
 40	test('returns word and count pairs', () => {
 41	  assert.deepEqual(topWords('apple', 1), [{ word: 'apple', count: 1 }]);
 42	});
 43	
 44	test('orders words by count, highest first', () => {
 45	  assert.deepEqual(topWords('pear apple apple fig fig fig', 3), [
 46	    { word: 'fig', count: 3 },
 47	    { word: 'apple', count: 2 },
 48	    { word: 'pear', count: 1 },
 49	  ]);
 50	});
 51	
 52	test('throws a TypeError naming the function for a non-string', () => {
 53	  for (const bad of [undefined, null, 3, {}, ['apple']]) {
 54	    assert.throws(() => topWords(bad, 3), (err) => {
 55	      assert.ok(err instanceof TypeError);
 56	      assert.ok(err.message.startsWith('topWords:'));
 57	      return true;
 58	    });
 59	  }
 60	});
 61	
 62	test('matches every row of the reference table', () => {
 63	  for (const [text, n, expected] of CASES) {
 64	    assert.deepEqual(topWords(text, n), expected, JSON.stringify([text, n]));
 65	  }
 66	});
 67	
 68	test('ranks the passage with ties broken alphabetically and stop words removed', () => {
 69	  assert.deepEqual(topWords(PASSAGE, 4), [
 70	    { word: 'keeper', count: 3 },
 71	    { word: 'lamp', count: 3 },
 72	    { word: 'night', count: 2 },
 73	    { word: 'tower', count: 2 },
 74	  ]);
 75	});
 76	
 77	test('lists every distinct passage word when n is large, once-only words last', () => {
 78	  assert.deepEqual(topWords(PASSAGE, 100), [
 79	    { word: 'keeper', count: 3 },
 80	    { word: 'lamp', count: 3 },
 81	    { word: 'night', count: 2 },
 82	    { word: 'tower', count: 2 },
 83	    { word: 'climbed', count: 1 },
 84	    { word: 'hand', count: 1 },
 85	    { word: 'lit', count: 1 },
 86	    { word: 'old', count: 1 },
 87	    { word: 'older', count: 1 },
 88	    { word: 'shook', count: 1 },
 89	    { word: 'storm', count: 1 },
 90	  ]);
 91	});
 92	
 93	test('throws a RangeError naming the function for an invalid n', () => {
 94	  for (const bad of [-1, 1.5, NaN, Infinity, -Infinity, '3', undefined, null]) {
 95	    assert.throws(() => topWords('apple', bad), (err) => {
 96	      assert.ok(err instanceof RangeError, String(bad));
 97	      assert.ok(err.message.startsWith('topWords:'), String(bad));
 98	      return true;
 99	    });
100	  }
101	});
102	
103	test('checks the text before n', () => {
104	  assert.throws(() => topWords(5, -1), TypeError);
105	});
106	
107	test('returns every distinct word when n exceeds their number', () => {
108	  assert.deepEqual(topWords('pear apple pear', 10), [
109	    { word: 'pear', count: 2 },
110	    { word: 'apple', count: 1 },
111	  ]);
112	});
113	
114	test('folds case, including non-ASCII letters', () => {
115	  assert.deepEqual(topWords('Éclair éclair ÉCLAIR Apple apple', 5), [
116	    { word: 'éclair', count: 3 },
117	    { word: 'apple', count: 2 },
118	  ]);
119	});
120	
121	test('folds the typographic apostrophe into the straight one', () => {
122	  assert.deepEqual(topWords('keeper’s keeper\'s Keeper’s', 5), [
123	    { word: "keeper's", count: 3 },
124	  ]);
125	});
126	
127	test('keeps contractions and hyphenated compounds whole', () => {
128	  assert.deepEqual(topWords("don't well-known don't", 5), [
129	    { word: "don't", count: 2 },
130	    { word: 'well-known', count: 1 },
131	  ]);
132	});
133	
134	test('counts numbers as words', () => {
135	  assert.deepEqual(topWords('42 42 apple', 5), [
136	    { word: '42', count: 2 },
137	    { word: 'apple', count: 1 },
138	  ]);
139	});
140	
141	test('skips stop words in any case', () => {
142	  assert.deepEqual(topWords('The THE the Apple', 5), [{ word: 'apple', count: 1 }]);
143	});
144	
145	test('skips all 36 stop words', () => {
146	  const stop = ('a an and are as at be by for from had has have he her his i in is it its of on or ' +
147	    'she that the their there they this to was were will with').split(' ');
148	  assert.equal(stop.length, 36);
149	  assert.deepEqual(topWords(stop.join(' ') + ' zebra', 100), [{ word: 'zebra', count: 1 }]);
150	});
151	
152	test('breaks ties by code unit, so upper-case-folded and accented words sort after plain ones', () => {
153	  assert.deepEqual(topWords('zebra éclair apple mango', 4).map((e) => e.word), [
154	    'apple', 'mango', 'zebra', 'éclair',
155	  ]);
156	});
157	
158	test('returns fresh objects and arrays on every call', () => {
159	  const first = topWords('apple apple pear', 2);
160	  first[0].count = 99;
